import{_ as r,o as i,c as a,a3 as s,j as e,a as t}from"./chunks/framework.z_KJ15Ep.js";const d="/bilder/import-export-statistik/import-uvd.png",v=JSON.parse('{"title":"Unterrichtsdaten aus UVD.TXT importieren","description":"","frontmatter":{"title":"Unterrichtsdaten aus UVD.TXT importieren","source_pageid":907,"source_revision":5276},"headers":[],"relativePath":"schild3/import-export-statistik/unterrichts-daten-als-uvd-txt-verwaltung-import.md","filePath":"schild3/import-export-statistik/unterrichts-daten-als-uvd-txt-verwaltung-import.md"}'),l={name:"schild3/import-export-statistik/unterrichts-daten-als-uvd-txt-verwaltung-import.md"};function o(u,n,p,h,c,m){return i(),a("div",null,[...n[0]||(n[0]=[s('<h1 id="unterrichtsdaten-aus-uvd-txt-importieren" tabindex="-1">Unterrichtsdaten aus UVD.TXT importieren <a class="header-anchor" href="#unterrichtsdaten-aus-uvd-txt-importieren" aria-label="Permalink to &quot;Unterrichtsdaten aus UVD.TXT importieren&quot;">​</a></h1><p>Der UVD-Import verbindet die Unterrichtsplanung im Stundenplanprogramm mit der weiteren Datenpflege in SchILD-NRW. Die folgenden Schritte erläutern die Vorbereitung und die Übernahme der Exportdatei.</p><h2 id="exportdatei-bereitstellen" tabindex="-1">Exportdatei bereitstellen <a class="header-anchor" href="#exportdatei-bereitstellen" aria-label="Permalink to &quot;Exportdatei bereitstellen&quot;">​</a></h2><p>Übernehmen Sie die aus einem Stundenplanprogramm exportierte Grund-Unterrichtsverteilung. Individuelle Fach- und Kurszuweisungen sind anschließend gesondert zu ergänzen.</p><p><a href="/bilder/import-export-statistik/import-uvd.png"><img src="'+d+'" alt="Auswahl des Speicherorts einer UVD.TXT." loading="lazy"></a></p><p><em>Auswahl des Speicherorts einer UVD.TXT.</em></p><p>Bei einem Einsatz eines Stundenplanprogramms (WinPlan, Untis...) können die klassenrelevanten Daten der Unterrichtsverteilung in eine Datei <em>UVD.TXT</em> exportiert werden.</p><p>Öffnen Sie <strong>Verwaltung → Import → Unterrichts-Daten (als UVD.TXT)</strong>. Der Import übernimmt die grundlegende Unterrichtsverteilung (<strong>Grund-UVD</strong>) in das aktuelle Halbjahr der Schülerinnen und Schüler.</p><p>Individuelle Fach- und Kurszuweisungen müssen jedoch gesondert nach dem Import durchgeführt werden.</p><h2 id="uvd-datei-auswahlen-und-ubernehmen" tabindex="-1">UVD-Datei auswählen und übernehmen <a class="header-anchor" href="#uvd-datei-auswahlen-und-ubernehmen" aria-label="Permalink to &quot;UVD-Datei auswählen und übernehmen&quot;">​</a></h2><p>Geben Sie nach dem Anwählen des Menüpunktes den Speicherpfad der UVD.TXT an.</p>',11),e("div",{"data-hint-kind":"info",class:"info custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"info","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 11v6m0-10v.1"})]),t("Hinweis")]),e("p",null,[t("Eine Aktivierung der Option "),e("strong",null,"In Sekundarstufe II Kurse anlegen"),t(" ist eventuell nicht sinnvoll, wenn diese durch den Import aus den Programmen LuPO bzw. Kurs42 übernommen werden.")])],-1),e("hr",null,null,-1),e("p",null,[e("a",{href:"https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Unterrichts-Daten_als_UVD-TXT_(Verwaltung_Import)",target:"_blank",rel:"noreferrer"},"Originalartikel im Wiki"),t(" · Quellrevision 5276.")],-1)])])}const _=r(l,[["render",o]]);export{v as __pageData,_ as default};
